import {Battle,ORDERS,SKILLS,DIFFICULTY,WIDTH,HEIGHT,distance} from './battle.mjs';
import {PROLOGUE,epilogue,hints,loadRecords,saveRecord,difficultyName} from './campaign.mjs';
import {SeaRenderer} from './render3d.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let renderer=null;try{renderer=new SeaRenderer($('#sea'),{reducedMotion:window.matchMedia('(prefers-reduced-motion: reduce)').matches});}catch(error){$('#renderError').hidden=false;$('#renderError').textContent=error.message;}
const VIEW_KEY='minnezang-view';let savedView='rear';try{savedView=localStorage.getItem(VIEW_KEY)||'rear'}catch{}
if(renderer){renderer.setView(savedView);$('#viewMode').value=renderer.view}
let story='prologue',report=null,newBest=false,cutinKey='';
let b=new Battle({difficulty:$('#difficulty').value}),selected='stake',showRange=false,entryMode=false,last=performance.now(),acc=0,lastUI=0,lastLog=-1;
const clock=t=>`${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;
const descriptions={stake:'血海から杭を出現させ、10秒拘束・失血促進。移動と旋回を封じる。',lance:'助走速度で威力上昇。射出入力成功で×1.5。命中で押し戻す。',guard:'8秒間、近くの味方を防護。被害軽減・ノックバック無効。'};
function build(){ $('#shipList').innerHTML=b.ships.map(s=>`<button class="member" data-ship="${s.id}" style="--ship-color:${s.color}"><span class="member-crest">${SKILLS[s.id].crest}</span><span class="member-body"><span class="member-name"><strong>${s.name}</strong><span id="${s.id}-hp"></span></span><span class="bar hp"><i id="${s.id}-hpbar"></i></span><span class="bar blood"><i id="${s.id}-bloodbar"></i></span><span class="member-foot"><span id="${s.id}-status"></span><span id="${s.id}-blood"></span></span></span></button>`).join('');
 $('#skillDock').innerHTML=b.ships.map((s,i)=>`<button class="skill-button" data-skill="${s.id}" style="--ship-color:${s.color}" title="${s.name}〈${SKILLS[s.id].name}〉${descriptions[s.id]}"><span class="skill-ring"></span><span class="skill-crest">${SKILLS[s.id].crest}</span><span class="key">${['Q','W','E'][i]}</span><span class="skill-name">${SKILLS[s.id].name}</span><span class="skill-state" id="${s.id}-skillstate"></span></button>`).join('');
 $$('[data-ship]').forEach(el=>el.onclick=()=>{selected=el.dataset.ship;ui()});$$('[data-skill]').forEach(el=>el.onclick=()=>{b.toggleSkill(el.dataset.skill);ui()});}
function play(){if(story==='prologue'){story=null;ui();return}if(!renderer||renderer.lost)return;entryMode=false;if(b.mode==='ready')b.start();else if(b.mode==='running')b.pause();else if(b.mode==='paused')b.resume();else if(b.mode==='ended')reset();ui()}
function reset(){const auto=b.autoTiming,short=b.shortCutin;b=new Battle({difficulty:$('#difficulty').value});story=null;report=null;b.autoTiming=auto;b.shortCutin=short;entryMode=false;acc=0;lastLog=-1;build();ui()}
const esc=t=>String(t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const speech=lines=>lines.map(l=>`<p><b>${esc(l.speaker)}</b><span>${esc(l.text)}</span></p>`).join('');
function storyUI(){
 if(b.mode==='ended'&&!report){report=b.report();newBest=saveRecord(report);story='result';recordUI()}
 $('#story').hidden=!story;if(!story)return;const result=story==='result';
 $('#story').classList.toggle('lost',result&&report.result!=='victory');
 if(!result){$('#storyPlace').textContent=PROLOGUE.place;$('#storyTitle').textContent=PROLOGUE.title;$('#storyNote').textContent=`難易度：${difficultyName(b.difficulty)}　·　${DIFFICULTY[b.difficulty].note}`;$('#storyLines').innerHTML=speech(PROLOGUE.lines);$('#storyStats').hidden=true;$('#storyRank').hidden=true;$('#storyHints').innerHTML='';$('#storyGo').textContent='出撃準備へ ［Space］';$('#storyClose').hidden=true;return}
 const e=epilogue(report),r=report;$('#storyPlace').textContent=`戦果報告 · ${difficultyName(r.difficulty)} · ${clock(r.time)}`;$('#storyTitle').textContent=e.title;$('#storyRank').hidden=false;$('#storyRank').textContent=r.rank;$('#storyRank').dataset.rank=r.rank;$('#storyNote').textContent=e.note+(newBest&&r.result==='victory'?'　·　自己ベスト更新':'');$('#storyLines').innerHTML=speech(e.lines);
 $('#storyStats').hidden=false;$('#storyStats').innerHTML=[['連携',`${r.combos}回`],['PERFECT',`${r.perfect}回`],['与えた失血',r.dealt.bleed],['被害',r.taken],['蓄血',r.totalBlood],['生還',`${r.ships.filter(s=>!s.sunk).length} / 3`]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('');
 $('#storyHints').innerHTML=hints(r).map(h=>`<li>${esc(h)}</li>`).join('');$('#storyGo').textContent='再挑戦 ［Space］';$('#storyClose').hidden=false;
}
function recordUI(){const rec=loadRecords()[$('#difficulty').value];$('#bestRecord').textContent=rec?`最高評価 ${rec.rank}${rec.rank!=='—'?` · ${clock(rec.time)}`:''}`:'記録なし'}
function ui(){storyUI();const plan=b.canPlan();$('#clock').textContent=clock(b.time);$('#statusText').textContent={ready:'出撃準備',running:'交戦中',paused:'戦術ポーズ',cutin:'騎士の誓い',ended:'戦闘終了'}[b.mode];$('#mapState').textContent=`掲揚：${ORDERS[b.order].name}`;$('#playBtn').textContent={ready:'戦闘開始',running:'一時停止',paused:'再開',cutin:'発動中',ended:'再挑戦'}[b.mode];const body=document.body;if(body){body.dataset.mode=b.mode;body.dataset.plan=plan?'on':'';body.dataset.threat=b.enemy.attack&&b.mode!=='ended'?'on':'';body.dataset.story=story?'on':''}$('#playBtn').disabled=b.mode==='cutin'||!renderer||renderer.lost;$('#mapAlert').classList.toggle('hidden',!!story||!['ready','paused','ended'].includes(b.mode));$('#difficulty').disabled=b.mode!=='ready'&&b.mode!=='ended';$('#alertTitle').textContent=b.reason;$('#alertBody').textContent=b.detail;
 $('#monsterBar').style.width=$('#monsterLag').style.width=b.enemy.hp/b.enemy.maxHp*100+'%';$('#monsterText').textContent=`${Math.ceil(b.enemy.hp)} / ${b.enemy.maxHp}`;$('#formLabel').textContent=b.enemy.form===2?'第二形態':'第一形態';$('#bleedText').innerHTML=`<span class="bleed-label">失血</span>${'<i class="on"></i>'.repeat(b.enemy.bleed)}${'<i></i>'.repeat(5-b.enemy.bleed)}${b.enemy.rootUntil>b.time?'<span class="tag root">拘束中</span>':''}`;
 for(const s of b.ships){$(`#${s.id}-hp`).textContent=`${Math.ceil(s.hp)} / ${s.maxHp}`;$(`#${s.id}-hpbar`).style.width=s.hp/s.maxHp*100+'%';$(`#${s.id}-status`).textContent=s.hp<=0?'戦闘不能':s.status;$(`#${s.id}-blood`).textContent=`血${Math.floor(s.blood)}${s.blood>=25?` · Lv${Math.floor(s.blood/25)}`:''}`;$(`#${s.id}-bloodbar`).style.width=s.blood+'%';const el=$(`[data-skill="${s.id}"]`),queued=b.pendingSkills.includes(s.id);el.disabled=!plan||!!b.skillIssue(s.id)&&!queued;el.classList.toggle('queued',queued);el.classList.toggle('cooling',!queued&&!!b.skillIssue(s.id));$(`[data-ship="${s.id}"]`).classList.toggle('down',s.hp<=0);el.setAttribute('aria-pressed',String(queued));el.style.setProperty('--cd',String(Math.max(0,s.skillCd||0)/SKILLS[s.id].cooldown));const issue=b.skillIssue(s.id);$(`#${s.id}-skillstate`).textContent=queued?'予約':s.skillCd>0&&s.hp>0?String(Math.ceil(s.skillCd)):'';el.title=`${s.name}〈${SKILLS[s.id].name}〉${issue?`［${issue}］`:''}${descriptions[s.id]}`;$(`[data-ship="${s.id}"]`).classList.toggle('selected',selected===s.id);}
 const a=b.enemy.attack,counter=!a&&b.time<b.enemy.recoveryUntil;$('#threatStrip').classList.toggle('danger',!!a&&b.mode!=='ended');$('#threatStrip').classList.toggle('chance',counter);$('#threatTitle').textContent=a?(a.type==='slam'?'血潮の墜落':'薙ぎ払い'):'';$('#threatTime').textContent=a?(a.duration-a.age).toFixed(1):'';$('#threatText').textContent=b.mode==='ended'?b.reason:a?(a.type==='slam'?`${b.ship(a.targetId).name}の足元 · 赤い円の全艦に命中`:'赤い扇形の全艦に命中 · 集合か死守で備えよ'):(counter?'反撃チャンス！ 敵は後隙 · ジョストで押し戻せ':'');
 $$('.order-option').forEach(el=>{el.disabled=!plan;el.classList.toggle('selected',b.pending===el.dataset.order);el.classList.toggle('active',b.order===el.dataset.order)});$('#orderStatus').textContent=b.pending?'予約：'+ORDERS[b.pending].name:'';$('#orderHint').textContent=b.pending==='rally'?'海図（左上）か海面をクリック。再開後に集合します。':'旗と個別スキルは同時に予約できます。';$('#mapTip').textContent=entryMode?'海図をクリック：助走開始点（敵から165以上離す）':b.pending==='rally'?'海図をクリック：集合地点を自由指定':'';$('#entryBtn').disabled=!plan;$('#entryBtn').classList.toggle('active',entryMode);
 $('#queueText').textContent=b.pendingSkills.length?b.pendingSkills.map(id=>`${SKILLS[id].crest} ${SKILLS[id].name}`).join(' → '):'スキルを予約 → 再開で連続カットイン';$('#comboText').textContent=b.pendingSkills.includes('stake')&&b.pendingSkills.includes('lance')?'連携予約：茨の馬上槍試合':'';
 $('#cutin').hidden=b.mode!=='cutin';if(b.cutin){const id=b.cutin.ids[b.cutin.index],sk=SKILLS[id];$('#cutin').style.setProperty('--cutin-color',b.ship(id).color);$('#cutinCount').textContent=`${b.cutin.index+1} / ${b.cutin.ids.length}`;const key=`${b.time}:${b.cutin.index}:${id}`;if(key!==cutinKey){cutinKey=key;const el=$('#cutin');el.classList.remove('play');void el.offsetWidth;el.classList.add('play')}$('#cutinCrest').textContent=sk.crest;$('#cutinKnight').textContent=b.ship(id).name;$('#cutinSkill').textContent=sk.name;$('#cutinQuote').textContent=sk.quote;}
 $('#timingPanel').hidden=!b.timing;$('#timingBtn').disabled=!b.timing||b.timing.pressed||b.mode!=='running';if(b.timing){$('#timingNeedle').style.left=b.timing.progress*100+'%';$('#timingText').textContent=b.mode==='paused'?'戦術ポーズ中。再開すると入力を続けられます。':b.timing.pressed?b.lastTiming:'金色の範囲でFキー / ボタン。入力なしでも通常射出。';}
 const tip=$('#chartTip');if(tip)tip.textContent=entryMode?'クリック：助走開始点':b.canPlan()?'クリック：集合地点へ移動':'ポーズ中に移動を指示';drawChart();
 if(lastLog!==b.logs[0]?.id){lastLog=b.logs[0]?.id;$('#logList').innerHTML=b.logs.slice(0,4).map(l=>`<div class="log-entry ${l.type}"><time>${clock(l.time)}</time><span>${l.text}</span></div>`).join('')}
}
// 左上の海図：彼我の位置、血域、敵の攻撃範囲、集合・助走点を常に描く。ポーズ中のクリックで移動（集合）を指示する。
const chart=$('#chart'),chartCtx=chart?.getContext?.('2d'),TAU=Math.PI*2;
function drawChart(){if(!chartCtx)return;const dpr=Math.min(2,window.devicePixelRatio||1),w=chart.clientWidth||240,h=chart.clientHeight||156,cw=Math.round(w*dpr),ch=Math.round(h*dpr);if(chart.width!==cw||chart.height!==ch){chart.width=cw;chart.height=ch}const c=chartCtx,k=w/WIDTH,u=1/k,circle=(x,y,r)=>{c.beginPath();c.arc(x,y,r,0,TAU)};c.setTransform(dpr*k,0,0,dpr*h/HEIGHT,0,0);c.clearRect(0,0,WIDTH,HEIGHT);
 c.strokeStyle='#5fe3d61c';c.lineWidth=u;c.beginPath();for(let x=100;x<WIDTH;x+=100){c.moveTo(x,0);c.lineTo(x,HEIGHT)}for(let y=100;y<HEIGHT;y+=100){c.moveTo(0,y);c.lineTo(WIDTH,y)}c.stroke();
 for(const p of b.pools){c.fillStyle=`rgba(194,31,58,${Math.max(.08,Math.min(.5,p.life/24*.5))})`;circle(p.x,p.y,p.radius);c.fill()}
 const a=b.enemy.attack;if(a&&b.mode!=='ended'){c.beginPath();if(a.type==='slam')c.arc(a.x,a.y,a.range,0,TAU);else{c.moveTo(a.x,a.y);c.arc(a.x,a.y,a.range,a.angle-a.arc,a.angle+a.arc);c.closePath()}c.fillStyle='#ff4d5e44';c.fill();c.strokeStyle='#ff4d5e';c.lineWidth=1.5*u;c.stroke()}
 if(showRange)for(const s of b.ships)if(s.hp>0&&s.id===selected){c.setLineDash([6*u,5*u]);c.strokeStyle=s.color+'88';c.lineWidth=u;circle(s.x,s.y,s.range);c.stroke();c.setLineDash([])}
 const mark=(p,color,label)=>{if(!p)return;c.strokeStyle=color;c.lineWidth=2*u;c.beginPath();c.moveTo(p.x-14,p.y-14);c.lineTo(p.x+14,p.y+14);c.moveTo(p.x+14,p.y-14);c.lineTo(p.x-14,p.y+14);c.stroke();c.fillStyle=color;c.font=`700 ${11*u}px sans-serif`;c.textAlign='center';c.textBaseline='bottom';c.fillText(label,p.x,p.y-16)};
 mark(b.pending==='rally'?b.pendingRally:b.order==='rally'?b.rally:null,'#9db8ff','集合');mark(b.entry,'#f2cf7c','助走');
 const e=b.enemy;c.fillStyle=e.rootUntil>b.time?'#c21f3a':'#ff4d5e';c.strokeStyle='#fff';c.lineWidth=1.5*u;c.beginPath();c.moveTo(e.x+Math.cos(e.angle)*44,e.y+Math.sin(e.angle)*44);c.lineTo(e.x+Math.cos(e.angle+2.4)*32,e.y+Math.sin(e.angle+2.4)*32);c.lineTo(e.x+Math.cos(e.angle-2.4)*32,e.y+Math.sin(e.angle-2.4)*32);c.closePath();c.fill();c.stroke();
 for(const s of b.ships){const down=s.hp<=0;c.globalAlpha=down?.4:1;circle(s.x,s.y,22);c.fillStyle=s.color;c.fill();c.strokeStyle='#06121f';c.lineWidth=u;c.stroke();if(s.id===selected){circle(s.x,s.y,34);c.strokeStyle='#fff';c.lineWidth=1.5*u;c.stroke()}if(s.id==='stake'){circle(s.x,s.y,8);c.fillStyle='#06121f';c.fill()}c.globalAlpha=1}
}
function chartPoint(ev){const r=chart.getBoundingClientRect();return {x:(ev.clientX-r.left)/r.width*WIDTH,y:(ev.clientY-r.top)/r.height*HEIGHT}}
chart?.addEventListener('click',ev=>{const p=chartPoint(ev);if(entryMode){if(b.setEntry(p.x,p.y))entryMode=false}else if(b.canPlan()){if(b.pending!=='rally')b.setOrder('rally');b.setRally(p.x,p.y)}ui()});
// Phones play in landscape. Android allows locking only in fullscreen; iOS ignores it and the CSS rotate hint covers portrait.
const touch=window.matchMedia('(pointer: coarse)').matches;
function landscape(){if(!touch||document.fullscreenElement||!document.documentElement?.requestFullscreen)return;document.documentElement.requestFullscreen({navigationUI:'hide'}).then(()=>screen.orientation?.lock?.('landscape')).catch(()=>{})}
$('#playBtn').onclick=()=>{landscape();play()};$('#storyGo').onclick=()=>{landscape();if(story==='result')reset();else story=null;ui()};$('#storyClose').onclick=()=>{story=null;ui()};$('#difficulty').onchange=()=>{if(b.mode==='ready'||b.mode==='ended'){const keep=story==='prologue';reset();if(keep)story='prologue'}recordUI();ui()};$('#resetBtn').onclick=reset;$('#entryBtn').onclick=()=>{entryMode=!entryMode;ui()};$('#rangeBtn').onclick=()=>{showRange=!showRange;$('#rangeBtn').classList.toggle('active',showRange)};$('#helpBtn').onclick=()=>{if(b.mode==='running')b.pause();$('#help').open=!$('#help').open;ui()};$('#helpClose').onclick=()=>{$('#help').open=false;ui()};$('#skipCutin').onclick=()=>{b.finishCutins();ui()};$('#autoTiming').onchange=e=>b.autoTiming=e.target.checked;$('#shortCutin').onchange=e=>b.shortCutin=e.target.checked;$('#timingBtn').onclick=()=>{b.pressTiming();ui()};
$$('.order-option').forEach(el=>el.onclick=()=>{entryMode=false;b.setOrder(el.dataset.order);ui()});$('#sea').addEventListener('click',ev=>{if(!renderer||renderer.lost)return;const p=renderer.point(ev);if(!p)return;if(entryMode){if(b.setEntry(p.x,p.y))entryMode=false;}else if(b.pending==='rally')b.setRally(p.x,p.y);else{const s=renderer.pickShip(ev,b)||b.ships.find(s=>distance(s,p)<50);if(s)selected=s.id}ui()});
$('#viewMode').onchange=e=>{renderer?.setView(e.target.value);try{localStorage.setItem(VIEW_KEY,e.target.value)}catch{}};$('#zoomIn').onclick=()=>renderer?.zoomBy(.85);$('#zoomOut').onclick=()=>renderer?.zoomBy(1.17);$('#cameraReset').onclick=()=>renderer?.resetCamera();
$('#sea').addEventListener('renderlost',()=>{if(b.mode==='cutin')b.finishCutins();b.pause('3D表示が停止しました','ページを再読み込みしてください。');$('#renderError').hidden=false;$('#renderError').textContent='3D描画が中断されました。ページを再読み込みしてください。';ui()});

document.addEventListener('keydown',ev=>{if(['INPUT','SELECT','TEXTAREA'].includes(ev.target.tagName)||ev.repeat)return;const key=ev.key.toLowerCase();if(story==='result'&&ev.code==='Space'&&ev.target.tagName!=='BUTTON'){ev.preventDefault();reset();ui();return}if(key==='f'){ev.preventDefault();b.pressTiming();ui();return}if(ev.code==='Space'&&ev.target.tagName!=='BUTTON'){ev.preventDefault();play()}if('123'.includes(key)&&key){b.setOrder({1:'charge',2:'rally',3:'hold'}[key]);entryMode=false;}if(['q','w','e'].includes(key))b.toggleSkill({q:'stake',w:'lance',e:'guard'}[key]);ui()});
const portrait=window.matchMedia('(orientation: portrait) and (pointer: coarse) and (max-width: 820px)');portrait.addEventListener?.('change',e=>{if(!e.matches)return;if(b.mode==='cutin')b.finishCutins();if(b.mode==='running')b.pause('縦向きのため停止','横向きに戻して再開してください。');ui()});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(b.mode==='cutin')b.finishCutins();if(b.mode==='running')b.pause('画面を離れたため停止','戻ったら再開してください。');ui()}});
function frame(now){const dt=Math.min(.08,Math.max(0,(now-last)/1000));last=now;b.advancePresentation(dt);if(b.mode==='running'){acc+=dt*(b.timing?.12:1);while(acc>=.025&&b.mode==='running'){b.step(.025);acc-=.025}}else acc=0;if(now-lastUI>40){ui();lastUI=now}renderer?.render(b,selected,showRange);requestAnimationFrame(frame)}
build();recordUI();ui();requestAnimationFrame(frame);
